final_response:
{"policy":"permit (
    principal is Picker,
    action == Action::"pickOrder",
    resource is Order
)
when {
    context.hasBadgedInOnSiteForShift
};

forbid (
    principal,
    action == Action::"pickOrder",
    resource is Order
)
when {
    (principal is Picker || principal is ForkliftOperator) &&
    !context.hasBadgedInOnSiteForShift
};

forbid (
    principal,
    action == Action::"pickOrder",
    resource is Order
)
when {
    ((principal is Picker && principal.user == resource.requestedBy) ||
     (principal is ForkliftOperator && principal.user == resource.requestedBy)) &&
    !resource.crossesBulkPickThreshold
};"}
